                   RecipeIngredient(amount: "4 cups", item: "plain whole-milk yogurt"),
                   RecipeIngredient(amount: "1", item: "large egg"),
                   RecipeIngredient(amount: "2 tbsp", item: "cornstarch"),
                   RecipeIngredient(amount: "3 tbsp", item: "butter or olive oil"),
                   RecipeIngredient(amount: "4 cloves", item: "garlic, minced"),
                   RecipeIngredient(amount: "1 tbsp", item: "dried mint"),
                   RecipeIngredient(amount: "1 cup", item: "long-grain or short-grain rice, cooked, to serve"),
               ],
               steps: [
                   "Knead the flour, water and 3/4 teaspoon of salt into a smooth dough, cover and rest 30 minutes. Meanwhile cook the onion, lamb, allspice and 1/2 teaspoon of salt until browned, and cool it.",
                   "Roll the dough thin and cut 2-inch circles. Put a small dab of filling on each, fold into a half-moon, seal the edge, then pull the two corners together and pinch into a little hat.",
                   "Spread the dumplings on a parchment-lined sheet and bake at 375 F for 10 minutes until barely golden; this keeps them from dissolving in the sauce.",
                   "Whisk the yogurt with the egg, cornstarch and remaining salt in a heavy pot until completely smooth; the egg and starch are the insurance against splitting.",
                   "Set the pot over medium heat and stir constantly in one direction until the yogurt loosens, then thickens, and comes to a lazy bubble; never walk away during this stage.",
                   "Slide the dumplings into the yogurt, drop the heat low and simmer gently 15 minutes, stirring now and then, until the dough is tender all the way through.",
                   "Fry the garlic in the butter until it just turns gold, stir in the dried mint off the heat, and swirl this into the pot right before serving over rice.",
               ],
               note: "Stabilized yogurt breaks the moment it boils hard or gets ignored; stir one direction, keep the flame gentle and it stays silk from stove to bowl.",
               shortcut: "Fold small wonton wrappers around the filling instead of making dough; they are thinner than tradition wants but poach beautifully in the yogurt."),
        Recipe(dishID: "lebanon-samkeharra", serves: 4, prepMinutes: 20, cookMinutes: 35, difficulty: 2,
               ingredients: [
                   RecipeIngredient(amount: "2 lb", item: "whole branzino or red snapper, gutted and scaled (or 4 thick cod fillets)"),
                   RecipeIngredient(amount: "2 tsp", item: "salt"),
                   RecipeIngredient(amount: "4 tbsp", item: "olive oil"),
                   RecipeIngredient(amount: "2/3 cup", item: "tahini, stirred well"),
                   RecipeIngredient(amount: "1/2 cup", item: "fresh lemon juice"),
                   RecipeIngredient(amount: "1/2 cup", item: "walnuts, chopped"),
                   RecipeIngredient(amount: "1", item: "onion, sliced thin"),
                   RecipeIngredient(amount: "4 cloves", item: "garlic, minced"),
                   RecipeIngredient(amount: "1", item: "red chili, minced (or 1 tsp red pepper flakes)"),
                   RecipeIngredient(amount: "1 tsp", item: "ground coriander"),
                   RecipeIngredient(amount: "1 cup", item: "fresh cilantro, chopped, divided"),
                   RecipeIngredient(amount: "1/2 cup", item: "warm water"),
               ],
               steps: [
                   "Heat the oven to 425 F. Slash the fish twice on each side, rub inside and out with salt and 2 tablespoons of oil, and set it on a lined sheet pan.",
                   "Roast 20 to 25 minutes, until the flesh at the deepest slash flakes when nudged with a fork and pulls from the bone.",
                   "While it roasts, soften the onion in the remaining oil over medium heat, then add the garlic, chili and ground coriander and cook one fragrant minute more.",
                   "Whisk the tahini with the lemon juice; it will seize into paste first, then loosen as you whisk in the warm water until it pours like cream.",
                   "Pour the tahini into the skillet with the onions, add most of the cilantro and the walnuts, and warm gently 3 to 4 minutes, stirring, until it thickens to a coating sauce; never let it boil.",
                   "Move the fish to a platter, spoon the hot sauce generously over the whole thing and scatter the last of the cilantro and a few extra walnuts on top.",
                   "Serve at the table with bread or rice, encouraging people to pull the fish apart and drag every piece through the sauce.",
               ],
               note: "Tahini thickens fast as it heats; keep spare warm water at the stove and loosen the sauce until it pours, not spreads.",
               shortcut: "Cod or halibut fillets skip the whole-fish theater and roast in 12 minutes; you lose the platter drama but none of the sauce."),
        Recipe(dishID: "lebanon-knafeh", serves: 8, prepMinutes: 30, cookMinutes: 45, difficulty: 2,
               ingredients: [
                   RecipeIngredient(amount: "1 lb", item: "frozen kataifi (shredded filo), thawed (look in Middle Eastern or Greek markets)"),
                   RecipeIngredient(amount: "1 cup", item: "unsalted butter, melted"),
                   RecipeIngredient(amount: "12 oz", item: "low-moisture mozzarella, shredded"),
                   RecipeIngredient(amount: "1 cup", item: "whole-milk ricotta"),
                   RecipeIngredient(amount: "2 tbsp", item: "fine semolina"),
                   RecipeIngredient(amount: "1 1/2 cups", item: "sugar"),
                   RecipeIngredient(amount: "3/4 cup", item: "water"),
                   RecipeIngredient(amount: "1 tsp", item: "lemon juice"),
                   RecipeIngredient(amount: "1 tbsp", item: "orange blossom water"),
                   RecipeIngredient(amount: "1/4 cup", item: "pistachios, ground fine"),
                   RecipeIngredient(amount: "8", item: "sesame buns or brioche rolls, split (optional but traditional)"),
               ],
               steps: [
                   "Boil the sugar, water and lemon juice for 10 minutes until lightly syrupy, stir in the orange blossom water off the heat, and let it cool completely.",
                   "Pull the kataifi apart into a bowl and chop it roughly into inch-long pieces, then work the melted butter through with your hands until every strand is coated and glistening.",
                   "Press two-thirds of the buttered pastry firmly into a buttered 10-inch oven-safe skillet or 9-by-13-inch pan, packing the base and a shallow rim with the bottom of a measuring cup.",
                   "Mix the mozzarella, ricotta and semolina, spread it over the base leaving a half-inch border, and scatter the remaining pastry loosely on top.",
                   "Bake at 375 F for 35 to 45 minutes, until the top is deep gold and you can see the edges bubbling and browned when you tilt the pan.",
                   "Pour the cooled syrup evenly over the hot knafeh the moment it comes out; it will hiss and soak in. Rest 5 minutes, no longer.",
                   "Scatter the ground pistachios over the top, cut wedges while the cheese still pulls, and serve hot, tucked into a sesame roll if you want the Beirut breakfast experience.",
               ],
               note: "Serve it hot or not at all; once the cheese sets, no reheating fully brings back the pull, so time it to the table.",
               shortcut: "Mozzarella plus ricotta stands in for hard-to-find akkawi; soak slices of salted halloumi in water and shred them if you want closer to the real salt-edge."),
        Recipe(dishID: "lebanon-mujaddara", serves: 4, prepMinutes: 10, cookMinutes: 50, difficulty: 1,
               ingredients: [
                   RecipeIngredient(amount: "1 cup", item: "brown or green lentils, rinsed"),
                   RecipeIngredient(amount: "3/4 cup", item: "long-grain rice, rinsed"),
                   RecipeIngredient(amount: "3", item: "large onions, halved and sliced thin"),
                   RecipeIngredient(amount: "1/2 cup", item: "olive oil"),
                   RecipeIngredient(amount: "1 tsp", item: "ground cumin"),
                   RecipeIngredient(amount: "2 tsp", item: "salt"),
                   RecipeIngredient(amount: "4 cups", item: "water"),
                   RecipeIngredient(amount: "1 cup", item: "plain yogurt, to serve"),
                   RecipeIngredient(amount: "a handful", item: "dill pickles or pickled turnips, to serve"),
               ],
               steps: [
                   "Fry the onions in the olive oil in a wide pot over medium-high heat, stirring often, 20 to 25 minutes, until deep mahogany with crisp near-black edges; do not stop at golden.",
                   "Lift out half the onions onto paper towels for the topping; they will crisp as they cool. Leave the rest and the oil in the pot.",
                   "Simmer the lentils in the 4 cups of water in a separate pot for 12 minutes; they should still be firm at the center. Keep the cooking water.",
                   "Add the rice, cumin and salt to the onion pot, stir a minute in the oil, then add the lentils and 2 1/2 cups of their cooking liquid.",
                   "Bring to a boil, then cover, drop the heat to its lowest and cook 18 minutes without lifting the lid.",
                   "Rest off the heat, covered, for 10 minutes, then fluff gently with a fork; the grains should be distinct, the lentils soft but whole.",
                   "Serve warm or at room temperature, piled with the reserved crisp onions, with yogurt and pickles on the side.",
               ],
               note: "The onions must go past golden into true dark brown; that burnt-sweet edge is the flavor of the dish, and timidity here makes it bland.",
               shortcut: "Canned lentils, drained, go in with the rice and skip the pre-simmer; texture goes softer, so cut the liquid by half a cup."),
    ]

    private static let recipes_georgia: [Recipe] = [
        Recipe(dishID: "georgia-khachapuri", serves: 4, prepMinutes: 40, cookMinutes: 25, difficulty: 2,
               ingredients: [
                   RecipeIngredient(amount: "3 cups", item: "all-purpose flour"),
                   RecipeIngredient(amount: "2 tsp", item: "instant yeast"),
                   RecipeIngredient(amount: "1 tsp", item: "sugar"),
                   RecipeIngredient(amount: "1 1/4 tsp", item: "salt"),
                   RecipeIngredient(amount: "1 cup", item: "warm milk"),
                   RecipeIngredient(amount: "3 tbsp", item: "olive oil"),
                   RecipeIngredient(amount: "12 oz", item: "low-moisture mozzarella, shredded (stand-in for sulguni)"),
                   RecipeIngredient(amount: "6 oz", item: "feta cheese, crumbled (stand-in for imeruli)"),
                   RecipeIngredient(amount: "4", item: "large egg yolks"),
                   RecipeIngredient(amount: "4 tbsp", item: "butter, in pats"),
               ],
               steps: [
                   "Mix the flour, yeast, sugar and salt, add the warm milk and olive oil, and knead 8 minutes to a soft, supple dough. Cover and rise until doubled, about 1 hour.",
